completionsAPI.python:
from openai import OpenAI
import os

client = OpenAI(
    # 如果没有配置环境变量，请用阿里云百炼API Key替换：api_key="sk-xxx"
    api_key=os.getenv("DASHSCOPE_API_KEY"),
    base_url="https://[workspace-id].cn-beijing.maas.aliyuncs.com/compatible-mode/v1",
)

# 多模态消息：文本 + 图片
messages = [
    {
        "role": "user",
        "content": [
            {"type": "text", "text": "图中描绘的是什么景象？"},
            {
                "type": "image_url",
                "image_url": {
                    "url": "https://help-static-aliyun-doc.aliyuncs.com/file-manage-files/zh-CN/20241022/emyrja/dog_and_girl.jpeg"
                },
            },
        ],
    }
]

completion = client.chat.completions.create(
    model="xiaomi/mimo-v2.6-pro-ultraspeed",  # 您可以按需更换为其它深度思考模型
    messages=messages,
    extra_body={"enable_thinking": True},
    stream=True,
)

is_answering = False  # 是否进入回复阶段
print("\n" + "=" * 20 + "思考过程" + "=" * 20)
for chunk in completion:
    # 最后一个 chunk 的 choices 可能为空，需要跳过
    if not chunk.choices:
        continue
    delta = chunk.choices[0].delta
    if hasattr(delta, "reasoning_content") and delta.reasoning_content is not None:
        if not is_answering:
            print(delta.reasoning_content, end="", flush=True)
    if hasattr(delta, "content") and delta.content:
        if not is_answering:
            print("\n" + "=" * 20 + "完整回复" + "=" * 20)
            is_answering = True
        print(delta.content, end="", flush=True)
print()

completionsAPI.nodejs:
import OpenAI from "openai";
import process from 'process';

// Initialize the OpenAI client
const openai = new OpenAI({
    apiKey: process.env.DASHSCOPE_API_KEY, // Read from the environment variable
    baseURL: 'https://[workspace-id].cn-beijing.maas.aliyuncs.com/compatible-mode/v1'
});
let isAnswering = false;
async function main() {
    try {
        // Multimodal messages: text + image
        const messages = [
            {
                role: 'user',
                content: [
                    { type: 'text', text: '图中描绘的是什么景象？' },
                    {
                        type: 'image_url',
                        image_url: {
                            url: 'https://help-static-aliyun-doc.aliyuncs.com/file-manage-files/zh-CN/20241022/emyrja/dog_and_girl.jpeg'
                        }
                    }
                ]
            }
        ];
        const stream = await openai.chat.completions.create({
            model: 'xiaomi/mimo-v2.6-pro-ultraspeed',
            messages,
            stream: true,
            enable_thinking: true
        });
        console.log('\n' + '='.repeat(20) + '思考过程' + '='.repeat(20));
        for await (const chunk of stream) {
            // The last chunk may have empty choices, skip it
            if (!chunk.choices || chunk.choices.length === 0) continue;
            const delta = chunk.choices[0].delta;
            if (delta.reasoning_content !== undefined && delta.reasoning_content !== null) {
                if (!isAnswering) {
                    process.stdout.write(delta.reasoning_content);
                }
            }
            if (delta.content !== undefined && delta.content) {
                if (!isAnswering) {
                    console.log('\n' + '='.repeat(20) + '完整回复' + '='.repeat(20));
                    isAnswering = true;
                }
                process.stdout.write(delta.content);
            }
        }
        console.log();
    } catch (error) {
        console.error('Error:', error);
    }
}
main();
